WITH cleaned AS (SELECT id, supplier_name, city, UPPER(country) AS country_upper, COALESCE(city, 'OTHER') AS city_filled FROM suppliers WHERE city IS NOT NULL), base AS (SELECT id, country_upper, city_filled, TRIM(supplier_name) AS clean_supplier_name FROM cleaned WHERE city = 'London'), with_last AS (SELECT s.*, x.launch_date FROM base s JOIN LATERAL (SELECT c.launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.price DESC, c.id DESC LIMIT 1) x ON TRUE), kept AS (SELECT s.* FROM with_last s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.launch_date >= s.launch_date)), valid AS (SELECT id, country_upper, city_filled, launch_date, DATE_TRUNC('MONTH', launch_date) AS launch_date_period FROM kept WHERE launch_date < '2025-04-03'), totals AS (SELECT DATE_TRUNC('WEEK', launch_date) AS week_start, DATE_TRUNC('YEAR', launch_date) AS year_start, COUNT(*) AS num_rows, MIN(launch_date_period) AS started_at, COUNT(*) AS cnt FROM valid GROUP BY DATE_TRUNC('WEEK', launch_date), DATE_TRUNC('YEAR', launch_date) HAVING num_rows >= 1) SELECT week_start, year_start, started_at FROM totals ORDER BY year_start;
